# frozen_string_literal: true
module Axiom
  module PolicyContent
    TITLES={'terms-of-service'=>'Syarat Layanan','privacy-policy'=>'Kebijakan Privasi','fee-policy'=>'Kebijakan Biaya','withdrawal-policy'=>'Kebijakan Penarikan','refund-policy'=>'Kebijakan Refund dan Sengketa','acceptable-use-policy'=>'Kebijakan Penggunaan yang Diperbolehkan','complaint-policy'=>'Kebijakan Pengaduan'}.freeze
    def self.sections(slug,c)
      owner=c['operator_name'];contact=c['contact_email'].to_s.strip;address=c['correspondence_address'].to_s.strip
      contact=contact.empty? ? 'tiket bantuan pada /dashboard/bantuan atau menu Bantuan Axiom Assistant' : contact
      privacy=c['privacy_email'].to_s.strip
      privacy=privacy.empty? ? contact : privacy
      case slug
      when 'terms-of-service'
        [
          ['Pengelola dan kontak',"Axiom Payment dikelola oleh #{owner}. #{address.empty? ? '' : "Alamat korespondensi: #{address}. "}Kontak resmi: #{contact}. Identitas ini adalah pihak yang bertanggung jawab atas pengoperasian aplikasi; penyebutan merek bukan pernyataan bahwa Axiom Payment merupakan bank atau penyelenggara pembayaran berizin."],
          ['Ruang lingkup dan alur dana','Axiom Payment menyediakan akun, pembuatan invoice QRIS, pencatatan status pembayaran, perhitungan komisi, pengajuan penarikan manual, API dan kanal Telegram. Pembayaran menggunakan merchant utama bersama melalui provider. Dana diterima merchant utama; saldo pada dashboard merupakan hak penarikan menurut catatan transaksi, bukan rekening bank atau simpanan nasabah. Aktivitas aktual, hak penggunaan merchant, alur dana dan perjanjian provider harus memenuhi ketentuan Bank Indonesia. Tidak ada klaim izin, sertifikasi atau jaminan saldo dari regulator.'],
          ['Persyaratan akun dan tanggung jawab pelanggan','Pelanggan memberikan identitas dan rekening yang benar, memiliki kewenangan atas kegiatan usaha, menjaga akses akun, dan menggunakan layanan untuk transaksi yang sah. OTP email diperlukan saat registrasi. API key hanya disimpan pada server pelanggan. Pelanggan segera melaporkan akses tanpa izin; pengelola membantu pemeriksaan tanpa meminta password atau OTP melalui chat. Penautan Telegram bersifat pilihan dan dapat diputus melalui web.'],
          ['Pembayaran, komisi dan penarikan','Invoice baru mengenakan komisi 2% dari bruto, dibulatkan ke bawah ke Rupiah penuh tanpa minimum biaya, setelah pembayaran terverifikasi PAID. Tarif dibekukan saat invoice dibuat; snapshot invoice lama tetap berlaku. Hak penarikan berasal dari neto terbayar dikurangi reservasi dan penarikan yang sudah selesai. Pengajuan tidak berarti transfer otomatis; ketentuan biaya dan penarikan pada halaman masing-masing menjadi bagian perjanjian ini.'],
          ['Kewajiban pengelola dan provider','Pengelola menjaga pencatatan, kontrol akses, informasi biaya yang jelas, penanganan gangguan serta saluran pengaduan. Merchant bertanggung jawab atas barang/jasa dan kesesuaian penawaran kepada pembeli. Provider menjalankan fungsi pembayaran menurut kontraknya. Gangguan pihak ketiga dapat memengaruhi waktu layanan, tetapi tidak menghapus kewajiban pengelola menelusuri masalah dan membantu pemulihan. Tidak dijanjikan uptime mutlak, dukungan 24 jam, atau pencairan instan.'],
          ['Limit, pemeliharaan dan penangguhan','Pengelola dapat menetapkan limit, menjadwalkan pemeliharaan, meminta verifikasi yang relevan, dan menangguhkan aktivitas yang memiliki dasar risiko, pelanggaran atau kewajiban hukum. Alasan, cakupan, waktu dan evaluasi harus dicatat; pemberitahuan diberikan sejauh tidak dilarang hukum. Pelanggan dapat mengajukan keberatan. Penangguhan bukan hak menyita saldo atau menahan hak pelanggan tanpa batas; bagian yang tidak disengketakan diselesaikan sesuai verifikasi dan kewajiban hukum.'],
          ['Penghentian dan kewajiban tersisa','Pelanggan dapat meminta penutupan melalui tiket. Pengelola dapat menghentikan layanan dengan alasan yang dapat dipertanggungjawabkan dan pemberitahuan yang layak. Invoice, saldo, refund, sengketa dan kewajiban yang belum selesai tetap ditangani. Akses pengaduan dan permintaan pemulihan tidak otomatis dicabut karena pelanggan tidak menerima perubahan ketentuan baru.'],
          ['Perubahan dan persetujuan','Versi, tanggal berlaku dan isi ketentuan diarsipkan. Perubahan material diberitahukan secara jelas sebelum berlaku sesuai hukum dan kontrak. Tarif baru hanya diterapkan pada invoice baru setelah aktivasi. Persetujuan ToS dicatat terpisah dari aktivasi Telegram dan pemasaran; penerimaan kebijakan privasi bukan izin tanpa batas.'],
          ['Pengaduan, sengketa dan hukum yang berlaku','Ajukan tiket dengan referensi transaksi dan bukti yang relevan. Para pihak terlebih dahulu menelusuri dan menyelesaikan masalah secara beritikad baik. Bila belum selesai, pelanggan tetap berhak memakai lembaga penyelesaian sengketa konsumen, regulator berwenang, atau pengadilan sesuai hukum Indonesia. Tidak ada klausul yang menghapus seluruh tanggung jawab, membalik pembuktian secara tidak patut, atau membatasi hak yang dijamin UU Perlindungan Konsumen.']
        ]
      when 'privacy-policy'
        [
          ['Pengendali dan kontak privasi',"Pengelola #{owner} bertanggung jawab atas pemrosesan data yang dikendalikannya dalam Axiom Payment. Permintaan privasi disampaikan melalui #{privacy}.#{address.empty? ? '' : " Alamat korespondensi: #{address}."}"],
          ['Data yang diproses','Data meliputi username, email terverifikasi, hash password dan token, sesi, metadata API key, referensi invoice, nominal, komisi, status, rekening untuk penarikan, bukti operasional, log keamanan dan persetujuan kebijakan. Jika Telegram ditautkan, sistem memproses Telegram user ID, private chat ID, nama tampilan saat klaim, langkah percakapan, callback, pengaturan notifikasi serta metadata pengiriman. Tiket menyimpan pesan, lampiran terbatas, status, pengirim dan pemetaan pesan bot/operator.'],
          ['Tujuan dan dasar pemrosesan','Data akun dan transaksi diperlukan untuk pelaksanaan perjanjian layanan, autentikasi, pencatatan hak pelanggan dan penyelesaian pengajuan. Data tertentu disimpan untuk kewajiban hukum. Pencegahan penipuan, keamanan dan pembelaan hak dilakukan atas dasar yang sah, proporsional dan dengan memperhatikan hak subjek data. Telegram dipilih secara terpisah oleh pelanggan; pemasaran memerlukan dasar dan persetujuan yang terpisah bila diwajibkan. Data tidak digunakan untuk tujuan baru yang tidak sesuai tanpa dasar dan pemberitahuan yang diperlukan.'],
          ['Penerima dan transfer lintas negara','Akses diberikan secara terbatas kepada personel berwenang, provider pembayaran/merchant bridge, penyedia hosting dan email, serta Telegram ketika kanal itu digunakan. Otoritas menerima data hanya berdasarkan kewenangan yang sah. Telegram dan penyedia lain dapat memproses data di luar Indonesia; pengelola menilai dasar transfer dan perlindungan yang diwajibkan UU Pelindungan Data Pribadi sebelum mengaktifkan pemrosesan. Tidak ada janji bahwa data selalu berada di Indonesia.'],
          ['Keamanan dan pembatasan akses','Password disimpan sebagai hash, secret API tidak ditampilkan kembali, sesi dan penautan memakai token acak, dan akses dibatasi berdasarkan akun serta role. Rekening disamarkan dalam notifikasi. Lampiran tidak dijalankan dan tidak diperlakukan sebagai bukti pembayaran otomatis. Pengguna tidak boleh mengirim password, OTP atau secret melalui tiket/bot. Langkah keamanan mengurangi risiko, bukan jaminan bahwa insiden tidak mungkin terjadi. Insiden ditangani dan diberitahukan sesuai persyaratan hukum yang berlaku.'],
          ['Retensi',"Data akun: #{c['retention_accounts']}. Catatan transaksi, penarikan, komisi dan audit: #{c['retention_financial']}. Tiket dan lampiran: #{c['retention_support']}. Log teknis: #{c['retention_logs']}. Setelah tujuan dan dasar penyimpanan berakhir, data dihapus atau dianonimkan sesuai proses yang dapat dipertanggungjawabkan. Legal hold dan kewajiban hukum dapat menunda penghapusan dengan alasan yang dicatat."],
          ['Hak pengguna','Subjek data dapat meminta informasi, akses, salinan, koreksi, pembatasan, keberatan, penarikan persetujuan atau penghapusan sesuai dasar pemrosesan dan hukum. Identitas pemohon diverifikasi secara proporsional. Penarikan persetujuan tidak otomatis menghapus catatan yang diperlukan untuk kewajiban hukum, sengketa atau transaksi yang belum selesai. Keputusan penolakan disertai alasan dan jalur pengaduan yang tersedia.'],
          ['Memutus Telegram dan batas penghapusan','Pemutusan tautan membatalkan akses bot, callback, percakapan tertunda dan pengiriman ke tautan lama. Riwayat transaksi atau tiket yang masih memiliki dasar penyimpanan tetap tersedia melalui web. Pengelola tidak mengklaim dapat menghapus semua salinan pesan pada perangkat pengguna, Telegram atau infrastruktur pihak lain; permintaan kepada pihak tersebut mengikuti mekanismenya sendiri.'],
          ['Cookie dan perubahan kebijakan','Cookie sesi diperlukan untuk login dan perlindungan request. Kebijakan ini tidak menganggap cookie teknis sebagai persetujuan pemasaran. Perubahan material tujuan, penerima atau dasar pemrosesan diberitahukan, dinilai ulang, dan dimintakan persetujuan baru bila diwajibkan.']
        ]
      when 'fee-policy'
        [
          ['Tarif platform','Komisi invoice baru adalah 2% (200 basis poin), dihitung sebagai floor(nominal × 200 / 10000) dalam Rupiah penuh tanpa minimum biaya. Komisi diakui hanya untuk pembayaran yang berhasil dan terverifikasi PAID. Komisi ditentukan backend dan tidak dapat diubah oleh payload pelanggan. Pembuatan API yang gagal, pemeriksaan status, invoice menunggu dan kedaluwarsa tidak menghasilkan komisi diakui.'],
          ['Dasar pengenaan','Komisi merupakan imbalan layanan pengelola untuk pengelolaan invoice, verifikasi status, pencatatan dan layanan operasional yang benar-benar diberikan. Ini bukan tarif resmi bank, Telegram, Bank Indonesia atau regulator. Komisi dipotong dari bruto, bukan ditambahkan pada pembayaran pembeli.'],
          ['Snapshot dan contoh','Invoice baru Rp100.000 mencatat komisi Rp2.000 dan neto pelanggan Rp98.000 sebelum biaya provider lain yang benar-benar berlaku. Nominal invoice harus Rupiah bulat, minimum Rp1 dan maksimum Rp10.000.000. Invoice Rp1 menghasilkan komisi Rp0 dan neto Rp1. Tarif percentage_200bps dengan fee_rate_bps 200, nominal komisi dan neto dibekukan saat invoice dibuat, diakui setelah PAID. Invoice historis termasuk komisi tetap Rp2.500 (fixed_2500), komisi nol atau persentase lain tidak dihitung ulang meskipun dibayar setelah perubahan tarif.'],
          ['Biaya provider dan pendapatan pengelola','Biaya provider/MDR terpisah dari komisi platform. Sistem tidak merekayasa tarif provider atau memasukkannya sebagai potongan tambahan tanpa ketentuan yang jelas dan disepakati. Komisi 2% bukan jaminan laba bersih 2%, karena pengelola dapat menanggung biaya provider atau operasional. Tidak ada biaya penarikan tambahan yang dipungut aplikasi pada kebijakan ini.'],
          ['Refund dan koreksi','Perlakuan komisi saat refund ditentukan dengan mempertimbangkan layanan yang benar-benar diberikan, penyebab masalah, ketentuan provider dan hak pelanggan menurut hukum. Kesalahan sistem pengelola tidak menjadi alasan menahan seluruh biaya tanpa penilaian. Tidak ada ketentuan bahwa seluruh biaya selalu tidak dapat dikembalikan. Koreksi dicatat dan dijelaskan, bukan menghapus snapshot.'],
          ['Perubahan tarif','Perubahan material diberitahukan sebelum aktivasi sesuai kebutuhan hukum/kontrak dan hanya berlaku untuk invoice baru. API terautentikasi, web pemilik dan bot harus menampilkan snapshot yang sama. Checkout publik hanya menampilkan total pembayaran pembeli, tanpa komisi atau neto pemilik. Jika terdapat ketidaksesuaian, hentikan pembuatan baru yang terdampak dan ajukan tiket untuk pemeriksaan.']
        ]
      when 'withdrawal-policy'
        [
          ['Dasar saldo','Saldo tersedia berasal dari neto invoice PAID yang terverifikasi, dikurangi dana dicadangkan dan penarikan selesai. Saldo ini catatan hak pelanggan, bukan pembacaan rekening bank provider. Komisi pengelola tidak termasuk saldo pelanggan. Kesiapan transfer tetap diperiksa terhadap dana aktual dan ketentuan provider.'],
          ['Rekening tujuan','Pengguna memberikan bank, nomor rekening sebagai string dan nama pemilik yang benar. Rekening untuk alur Telegram harus diajukan pada halaman aman, diverifikasi dengan password, lalu diperiksa admin. Perubahan rekening membatalkan status verifikasi lama. Pengelola hanya meminta bukti kepemilikan relevan melalui kanal aman, bukan password atau OTP.'],
          ['Pengajuan dan otorisasi','Nominal harus rupiah bulat positif dan tidak melebihi saldo tersedia. Detail dan persetujuan harus diperiksa sebelum pengajuan. Bot dapat menyusun draf, tetapi otorisasi akhir memerlukan verifikasi tambahan di web. ID permintaan menghindari reservasi ganda saat respons hilang; pelanggan memeriksa riwayat sebelum membuat permintaan baru.'],
          ['Reservasi dan status','REQUESTED mencadangkan saldo. PROCESSING berarti pengelola sedang memproses, bukan bukti uang sudah terkirim. PAID hanya dicatat setelah transfer nyata dengan referensi unik. REJECTED memerlukan alasan dan mengembalikan reservasi tepat sekali. Status terminal tidak diulang. Tidak ada transfer bank otomatis atau perubahan saldo bebas oleh admin.'],
          ['Jadwal dan estimasi',"Jadwal operasional penarikan: #{c['withdrawal_schedule']}. Jam layanan: #{c['support_hours']}. Estimasi pengajuan 1–2 hari kalender, bukan janji pencairan instan atau jaminan batas waktu. Penundaan karena pemeriksaan, hari layanan provider atau gangguan dijelaskan melalui status/tiket sejauh informasinya tersedia."],
          ['Penolakan, penundaan dan keberatan','Permintaan dapat ditolak karena saldo tidak cukup, rekening tidak cocok, data belum dapat diverifikasi atau alasan risiko/hukum yang relevan. Keputusan harus dicatat, ditinjau dan diberitahukan sejauh diperbolehkan. Penundaan bukan penyitaan atau penahanan tanpa batas. Pelanggan dapat mengajukan keberatan melalui tiket dan memperoleh penjelasan serta langkah pemulihan.'],
          ['Kesalahan transfer','Segera laporkan referensi penarikan, waktu dan bukti yang relevan. Pengelola menelusuri dengan provider/bank dan membedakan kesalahan input pengguna dari kesalahan sistem/operasional. Pemulihan mengikuti fakta, kendali dana, kontrak dan hukum; tanggung jawab pengelola tidak dihapus secara menyeluruh.']
        ]
      when 'refund-policy'
        [
          ['Ruang lingkup','Kebijakan ini menangani pembayaran ganda, kesalahan sistem, konfirmasi terlambat, ketidaksesuaian nominal, sengketa dan permintaan pengembalian dana. Aplikasi tidak menyediakan refund bank otomatis. Keputusan dan pelaksanaan dilakukan melalui pemeriksaan dengan merchant/provider dan dicatat.'],
          ['Cara mengajukan','Buka tiket dan sertakan ID invoice, referensi provider bila tersedia, nominal, waktu, uraian masalah dan bukti yang relevan. Jangan mengirim password/OTP. Screenshot membantu penelusuran, bukan pengganti konfirmasi provider. Pengelola memberikan nomor tiket dan pembaruan status berdasarkan hasil pemeriksaan nyata.'],
          ['Pembayaran ganda dan konfirmasi terlambat','Satu transaksi provider tidak diklaim untuk dua invoice. Pembayaran sah yang dikonfirmasi setelah expiry diperiksa berdasarkan identitas transaksi, bukan countdown. Pembayaran ganda yang terbukti ditelusuri asal dan tujuan dan diselesaikan melalui refund atau pemulihan yang disepakati tanpa mengkredit saldo dua kali.'],
          ['Kesalahan sistem dan barang/jasa','Kesalahan pencatatan atau operasional pengelola diperiksa dan dikoreksi dengan bukti yang dapat ditelusuri. Merchant bertanggung jawab atas sengketa barang/jasa yang dijual; pengelola membantu penyediaan catatan dan koordinasi sesuai perannya. Perbedaan tanggung jawab ini tidak menghilangkan hak konsumen menuntut pemulihan dari pihak yang bertanggung jawab.'],
          ['Penilaian jumlah dan komisi','Jumlah yang dapat dikembalikan mempertimbangkan fakta pembayaran, layanan yang telah diberikan, penyebab masalah, biaya provider yang benar-benar dikenakan, persetujuan yang sah dan hukum. Komisi tidak otomatis hangus seluruhnya. Pengelola menjelaskan dasar potongan atau pengembalian, termasuk jika kesalahan berasal dari sistemnya sendiri.'],
          ['Waktu, metode dan bukti','Pengelola menginformasikan langkah, kebutuhan verifikasi, ketergantungan provider serta perkiraan setelah fakta cukup tersedia; tidak menjanjikan penyelesaian instan tanpa kendali atas provider. Rekening penerima diverifikasi untuk mencegah pengalihan dana. Referensi hasil disimpan dan status diperbarui.'],
          ['Sengketa dan eskalasi','Jika hasil diperselisihkan, pelanggan dapat mengajukan pemeriksaan ulang dengan bukti tambahan dan memakai jalur penyelesaian sengketa yang sah. Snapshot, audit dan riwayat tidak dihapus untuk menyembunyikan koreksi; koreksi keuangan memerlukan pencatatan kompensasi yang disetujui, bukan edit saldo bebas.']
        ]
      when 'acceptable-use-policy'
        [
          ['Penggunaan yang diperbolehkan','Gunakan akun/API/bot untuk usaha atau pembayaran yang sah, dengan hak atas merchant, identitas, rekening dan data yang digunakan. Hormati ketentuan provider, hukum, hak konsumen dan hak pihak lain.'],
          ['Aktivitas terlarang','Dilarang menggunakan layanan untuk penipuan, pencucian uang, transaksi barang/jasa ilegal, pemalsuan bukti pembayaran, pencurian identitas, pengambilalihan akun, penyalahgunaan data pribadi, penghindaran sanksi yang berlaku atau aktivitas lain yang dilarang hukum/provider. Dilarang mengaku sebagai pihak berizin tanpa dasar.'],
          ['Keamanan API dan bot','Dilarang mencoba membaca akun lain, menebak token/OTP, membagikan API secret, mengirim malware, mengeksploitasi callback, membanjiri layanan, atau mengulang request untuk menggandakan saldo. Gunakan pagination dan batas request; patuhi respons 429. Laporan kerentanan disampaikan melalui kontak resmi tanpa mengeksploitasi data pelanggan.'],
          ['Verifikasi risiko yang proporsional','Pengelola dapat meminta informasi yang relevan, membatasi fungsi atau menangguhkan aktivitas berisiko dengan alasan dan catatan pemeriksaan. Verifikasi dibatasi pada kebutuhan yang sah; tidak menjadi alasan meminta password pihak ketiga, menyita saldo atau memperluas pemrosesan data tanpa dasar.'],
          ['Tindakan dan keberatan','Tindakan menimbang tingkat risiko, bukti, dampak pada pelanggan dan kewajiban hukum. Peringatan, limit, penangguhan atau penghentian dijelaskan sejauh diizinkan dan dievaluasi. Pelanggan berhak menyampaikan keberatan melalui tiket. Hak atas saldo dan penyelesaian kewajiban tidak otomatis hilang karena penangguhan.']
        ]
      when 'complaint-policy'
        [
          ['Kanal dan jam layanan',"Pengaduan disampaikan melalui /dashboard/bantuan, menu Bantuan pada Axiom Assistant yang sudah ditautkan, atau #{contact}. Jam layanan: #{c['support_hours']}. Pesan di luar jam layanan masuk antrean. Pemberitahuan otomatis ditandai sebagai otomatis, bukan klaim pengelola sedang membaca."],
          ['Informasi yang diperlukan','Berikan subjek, uraian, akun yang terkait, ID invoice/penarikan, waktu, nominal dan hasil yang diminta. Lampiran dibatasi PNG/JPEG/PDF maksimal 2 MB; jangan kirim rahasia autentikasi atau data pihak lain yang tidak perlu. Bukti tambahan diminta secara proporsional.'],
          ['Nomor tiket dan kerahasiaan','Setiap percakapan memiliki nomor tiket. Riwayat web dan bot berasal dari tiket yang sama. Balasan operator dipetakan ke tiket/pelanggan yang benar, bukan pengirim terakhir. Catatan internal tidak diteruskan ke pelanggan; akses dibatasi berdasarkan peran.'],
          ['Tahapan pemeriksaan','OPEN berarti tiket baru; WAITING_ADMIN menunggu pengelola; WAITING_CUSTOMER menunggu informasi atau tanggapan pelanggan; CLOSED berarti percakapan ditutup. Pengelola menilai fakta, meminta informasi relevan, menelusuri catatan/provider, memberi pembaruan dan menyampaikan hasil beserta alasannya. Pelanggan dapat membuka kembali tiket ketika masalah belum selesai.'],
          ['Pembaruan dan eskalasi','Waktu penyelesaian bergantung pada kompleksitas, kelengkapan bukti dan pihak terkait. Pengelola tidak menjanjikan dukungan 24 jam yang belum tersedia, tetapi harus menjelaskan penundaan dan langkah berikutnya secara wajar. Keberatan atas hasil ditinjau ulang. Pelanggan tetap dapat menghubungi lembaga konsumen, regulator atau pengadilan yang berwenang sesuai hukum.'],
          ['Pemulihan dan anti-retaliasi','Pengaduan beritikad baik tidak menjadi alasan penghapusan akun, penyitaan saldo atau penutupan akses pemulihan. Kesalahan yang terbukti ditangani dengan langkah koreksi proporsional, catatan hasil dan koordinasi provider. Hak konsumen dan pelindungan data pribadi tetap berlaku.']
        ]
      else
        []
      end
    end
  end
end
